    "doo": "This treatment is a little more, as it includes an extended massage and a hydrating mask.",
    "dooTh": "ทรีตเมนต์นี้ราคาสูงขึ้นเล็กน้อยเพราะรวมการนวดที่ยาวขึ้นและมาส์กให้ความชุ่มชื้นค่ะ",
