    "dooTh": "แบบฟอร์มนี้ช่วยให้เราดูแลความปลอดภัยของคุณระหว่างทรีตเมนต์ค่ะ ใช้เวลาแค่แป๊บเดียว",
    "why": "Explains the reason behind a rule instead of only citing it.",
